cpptestai::CCppTestAI::CCppTestAI(springai::OOAICallback* callback):
		callback(callback),
		skirmishAIId(callback != NULL ? callback->GetSkirmishAIId() : -1),
		pauseWorkerRunning(false),
		pauseWorkerStop(false),
		workerTick(false),
		unpauseRequested(false),
		aiPausedGame(false),
		pauseSeconds(0),
		pauseDeadline(std::chrono::steady_clock::now())
		{}

cpptestai::CCppTestAI::~CCppTestAI() {
	StopPauseWorker();
}

void cpptestai::CCppTestAI::StartPauseWorker() {
	if (pauseWorkerRunning.load())
		return;

	pauseWorkerStop.store(false);
	pauseWorkerRunning.store(true);
	pauseWorker = std::thread(&CCppTestAI::PauseWorkerLoop, this);
}

void cpptestai::CCppTestAI::StopPauseWorker() {
	pauseWorkerStop.store(true);

	if (pauseWorker.joinable())
		pauseWorker.join();

	pauseWorkerRunning.store(false);
}

void cpptestai::CCppTestAI::PauseWorkerLoop() {
	while (!pauseWorkerStop.load()) {
		std::this_thread::sleep_for(std::chrono::milliseconds(100));
		workerTick.store(true);

		if (!aiPausedGame.load())
			continue;

		std::chrono::steady_clock::time_point deadline;
		{
			std::lock_guard<std::mutex> lock(pauseMutex);
			deadline = pauseDeadline;
		}

		if (std::chrono::steady_clock::now() >= deadline) {
			aiPausedGame.store(false);
			unpauseRequested.store(true);

			const std::unique_ptr<springai::Game> game(callback->GetGame());
			game->SetPause(false, "AI pause worker timeout reached");
		}
	}
}

void cpptestai::CCppTestAI::SetPauseForSeconds(int seconds) {
	if (seconds < 0)
		seconds = 0;

	pauseSeconds.store(seconds);
	{
		std::lock_guard<std::mutex> lock(pauseMutex);
		pauseDeadline = std::chrono::steady_clock::now() + std::chrono::seconds(seconds);
	}

	aiPausedGame.store(true);
	unpauseRequested.store(false);
}

void cpptestai::CCppTestAI::ProcessPauseWorkerState() {
	workerTick.exchange(false);

	if (unpauseRequested.exchange(false)) {
		aiPausedGame.store(false);
	}
}

struct fakeUnit {
	int id; 
	std::string name; 
	int range;
	springai::AIFloat3 pos;
	float hp;

	fakeUnit(int i, std::string n, int r, springai::AIFloat3 p, float h) : id(i), name(n), range(r), pos(p), hp(h){

	}
};

static const char* RADAR_UNKNOWN_NAME = "RADAR_UNKNOWN";

// Keep radar contacts separate from confirmed LOS contacts so uncertain
// detections do not overwrite identified enemy data.
static void UpsertFakeUnit(std::vector<fakeUnit>& units, int id, const std::string& name, int range, const springai::AIFloat3& pos, float hp) {
	auto it = std::find_if(units.begin(), units.end(), [id](const fakeUnit& u){
		return u.id == id;
	});

	if (it == units.end()) {
		units.emplace_back(id, name, range, pos, hp);
		return;
	}

	it->name = name;
	it->range = range;
	it->pos = pos;
	it->hp = hp;
}

static void EraseFakeUnitById(std::vector<fakeUnit>& units, int id) {
	units.erase(
		std::remove_if(
			units.begin(),
			units.end(),
			[id](const fakeUnit& unit) {
				return unit.id == id;
			}
		),
		units.end()
	);
}

